code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    row_walls = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    col_walls = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    row_ranges=[]
    start=0
    for r in row_walls:
        if start < r: row_ranges.append((start,r))
        start=r+1
    if start < h: row_ranges.append((start,h))
    col_ranges=[]
    start=0
    for c in col_walls:
        if start < c: col_ranges.append((start,c))
        start=c+1
    if start < w: col_ranges.append((start,w))
    marks={2:[],3:[]}
    for i,(r0,r1) in enumerate(row_ranges):
        for j,(c0,c1) in enumerate(col_ranges):
            colors={grid[r][c] for r in range(r0,r1) for c in range(c0,c1)}-{0,8}
            for color in colors:
                if color in marks: marks[color].append((i,j))
    painted={2:set(),3:set()}
    for color, pts in marks.items():
        painted[color].update(pts)
        for i,j in pts:
            same_row=[jj for ii,jj in pts if ii==i]
            same_col=[ii for ii,jj in pts if jj==j]
            if len(same_row)>1:
                for jj in range(min(same_row),max(same_row)+1): painted[color].add((i,jj))
            if len(same_col)>1:
                for ii in range(min(same_col),max(same_col)+1): painted[color].add((ii,j))
    out=[row[:] for row in grid]
    for i,j in painted[2] | painted[3]:
        r0,r1=row_ranges[i]; c0,c1=col_ranges[j]
        color=6 if (i,j) in painted[2] and (i,j) in painted[3] else (2 if (i,j) in painted[2] else 3)
        for r in range(r0,r1):
            for c in range(c0,c1): out[r][c]=color
    return out
'''
